import json, hashlib, copy
from pathlib import Path
P=Path('packet.json'); packet=json.loads(P.read_text()); entries={e['source_id']:e for e in packet['entries']}
PR='https://github.com/bitcoin/bitcoin/pull/26586'
units=[]; relations=[]; by={}
def ev(s,q,start=None):
 t=entries[s]['text']; i=t.index(q) if start is None else t.index(q,start)
 return {'source_id':s,'span':{'start':i,'end':i+len(q),'quote':q}}
def src(i): return packet['entries'][i]['source_id']
def ee(i,q,start=None): return ev(src(i),q,start)
def full(i): return ee(i,packet['entries'][i]['text'])
def id_ev(obj):
 if obj==PR: return [ee(24,PR)]
 for i,e in enumerate(packet['entries']):
  if obj in e['text']: return [ee(i,obj)]
 return []
def qual(u,description,evidence,attachment='scope_note',linked=None,rationale=None):
 u['proposition']['qualifiers'].append({'description':description,'evidence':evidence,'attachment':attachment,'linked_unit_id':linked,'rationale':rationale or 'Preserves a material condition or scope qualification of the focal proposition.'})
def component(u,symbol,text,quote=None,basis='explicit',role='local',note='',source=None,governor=None):
 s=source or u['source_id']; q=quote if quote is not None else text
 if s==u['source_id']:
  try: a=ev(s,q,u['span']['start']); assert a['span']['end']<=u['span']['end']
  except (ValueError,AssertionError): a=ev(s,q)
 else: a=ev(s,q)
 g=governor or {'source_id':u['source_id'],'span':copy.deepcopy(u['span'])}
 if basis!='explicit' and not note: note='The role is reconstructed from this utterance; the words alone do not explicitly supply this role in the chosen parse.'
 c={'symbol':symbol,'text':text,'basis':basis,'evidence':[a],'inference_note':note,'occurrence_role':role,'governing_span':g}
 u['components'].append(c); return c

